def _normalize_document_ids(value: Optional[Union[List[str], str]]) -> Optional[list[str]]:
    if isinstance(value, str):
        value = [x.strip() for x in value.split(",") if x.strip()]

    if isinstance(value, list):
        value = [str(x).strip() for x in value if str(x).strip()]
        return value or None

    return None

COMPANY_GENERAL_MACHINE_SENTINEL = "__MM_COMPANY_GENERAL__"


def _normalize_ai_scope(value: Optional[str]) -> str:
    s = str(value or "").strip().lower()

    if not s:
        return "machine_all"

    if s in {"machine", "machine_all", "machine_all_plus_company"}:
        return "machine_all"

    if s in {"company", "company_general", "company_only", "general"}:
        return "company_general"

    if s in {"document_ids", "documents", "document"}:
        return "document_ids"

    raise HTTPException(status_code=400, detail=f"Unsupported ai_scope: {value}")


def _resolve_query_scope(
    company_id: str,
    machine_id: Optional[str],
    bubble_document_id: Optional[str] = None,
    document_ids: Optional[Union[List[str], str]] = None,
    ai_scope: Optional[str] = None,
) -> dict:
    company_id = (company_id or "").strip()
    if not company_id:
        raise HTTPException(status_code=400, detail="Missing company_id")

    explicit_scope = bool(str(ai_scope or "").strip())
    resolved_scope = _normalize_ai_scope(ai_scope)

    machine_id = (machine_id or "").strip()
    bubble_document_id = (bubble_document_id or "").strip() or None
    doc_ids = _normalize_document_ids(document_ids)

    # Pagina Machines: solo conoscenza aziendale generale.
    # Usiamo un machine_id sentinella: con i filtri SQL aggiornati prenderà solo
    # machine_id NULL oppure machine_id = ''.
    if resolved_scope == "company_general":
        machine_id = COMPANY_GENERAL_MACHINE_SENTINEL
        bubble_document_id = None
        doc_ids = None

    # Compatibilità vecchia: se NON viene passato ai_scope ma arrivano document_ids
    # o bubble_document_id, mantieni il vecchio comportamento ristretto ai documenti.
    elif resolved_scope == "document_ids" or (not explicit_scope and (doc_ids or bubble_document_id)):
        resolved_scope = "document_ids"
        if not machine_id:
            machine_id = COMPANY_GENERAL_MACHINE_SENTINEL

    # Nuovo comportamento pulito: machine_all significa davvero tutta la macchina.
    # Se ai_scope è esplicito, ignora eventuali document_ids rimasti per errore da Bubble.
    else:
        resolved_scope = "machine_all"
        if not machine_id:
            raise HTTPException(status_code=400, detail="Missing machine_id")

        if explicit_scope:
            bubble_document_id = None
            doc_ids = None

    return {
        "company_id": company_id,
        "machine_id": machine_id,
        "bubble_document_id": bubble_document_id,
        "document_ids": doc_ids,
        "ai_scope": resolved_scope,
    }

def _fetch_dense_chunk_candidates(
    *,
    company_id: str,
    machine_id: str,
    q_vec_lit: str,
    candidate_k: int,
    doc_ids: Optional[list[str]] = None,
    bubble_document_id: Optional[str] = None,
    debug: bool = False,
) -> tuple[Optional[int], list[tuple]]:
    chunks_matching_filter = None

    conn = _db_conn()
    try:
        with conn.cursor() as cur:
            if doc_ids:
                if debug:
                    cur.execute(
                        """
                        SELECT COUNT(*)
                        FROM public.document_chunks
                        WHERE company_id=%s
                          AND bubble_document_id = ANY(%s)
                          AND embedding IS NOT NULL;
                        """,
                        (company_id, doc_ids),
                    )
                    chunks_matching_filter = int(cur.fetchone()[0] or 0)

                cur.execute(
                    """
                    SELECT bubble_document_id, chunk_index, page_from, page_to,
                           left(chunk_text, %s) AS snippet,
                           left(chunk_text, 2000) AS chunk_full,
                           1 - (embedding <=> %s::vector) AS similarity,
                           embedding,
                           CASE WHEN machine_id = %s THEN TRUE ELSE FALSE END AS exact_machine_scope
                    FROM public.document_chunks
                    WHERE company_id = %s
                      AND bubble_document_id = ANY(%s)
                      AND embedding IS NOT NULL
                    ORDER BY embedding <=> %s::vector, bubble_document_id, page_from, chunk_index
                    LIMIT %s;
                    """,
                    (ASK_SNIPPET_CHARS, q_vec_lit, machine_id, company_id, doc_ids, q_vec_lit, candidate_k),
                )

            elif bubble_document_id:
                bdid = bubble_document_id

                if debug:
                    cur.execute(
                        """
                        SELECT COUNT(*)
                        FROM public.document_chunks
                        WHERE company_id=%s
                          AND bubble_document_id=%s
                          AND embedding IS NOT NULL
                          AND (machine_id=%s OR machine_id IS NULL OR machine_id = '');
                        """,
                        (company_id, bdid, machine_id),
                    )
                    chunks_matching_filter = int(cur.fetchone()[0] or 0)

                cur.execute(
                    """
                    SELECT bubble_document_id, chunk_index, page_from, page_to,
                           left(chunk_text, %s) AS snippet,
                           left(chunk_text, 2000) AS chunk_full,
                           1 - (embedding <=> %s::vector) AS similarity,
                           embedding,
                           CASE WHEN machine_id = %s THEN TRUE ELSE FALSE END AS exact_machine_scope
                    FROM public.document_chunks
                    WHERE company_id = %s
                      AND bubble_document_id = %s
                      AND embedding IS NOT NULL
                      AND (machine_id = %s OR machine_id IS NULL OR machine_id = '')
                    ORDER BY embedding <=> %s::vector, bubble_document_id, page_from, chunk_index
                    LIMIT %s;
                    """,
                    (ASK_SNIPPET_CHARS, q_vec_lit, machine_id, company_id, bdid, machine_id, q_vec_lit, candidate_k),
                )

            else:
                if debug:
                    cur.execute(
                        """
                        SELECT COUNT(*)
                        FROM public.document_chunks
                        WHERE company_id=%s
                          AND embedding IS NOT NULL
                          AND (machine_id=%s OR machine_id IS NULL OR machine_id = '');
                        """,
                        (company_id, machine_id),
                    )
                    chunks_matching_filter = int(cur.fetchone()[0] or 0)

                cur.execute(
                    """
                    SELECT bubble_document_id, chunk_index, page_from, page_to,
                           left(chunk_text, %s) AS snippet,
                           left(chunk_text, 2000) AS chunk_full,
                           1 - (embedding <=> %s::vector) AS similarity,
                           embedding,
                           CASE WHEN machine_id = %s THEN TRUE ELSE FALSE END AS exact_machine_scope
                    FROM public.document_chunks
                    WHERE company_id = %s
                      AND embedding IS NOT NULL
                      AND (machine_id = %s OR machine_id IS NULL OR machine_id = '')
                    ORDER BY embedding <=> %s::vector, bubble_document_id, page_from, chunk_index
                    LIMIT %s;
                    """,
                    (ASK_SNIPPET_CHARS, q_vec_lit, machine_id, company_id, machine_id, q_vec_lit, candidate_k),
                )

            raw_rows = cur.fetchall()
            return chunks_matching_filter, raw_rows
    finally:
        conn.close()

def _raw_rows_to_dense_candidates(
    raw_rows: list[tuple],
    *,
    query_used: Optional[str] = None,
) -> list[dict]:
    candidates: list[dict] = []

    for row in raw_rows:
        if len(row) == 9:
            (
                bdid,
                chunk_index,
                page_from,
                page_to,
                snippet,
                chunk_full,
                similarity,
                embedding,
                exact_machine_scope,
            ) = row
        elif len(row) == 8:
            # Backward-compatible for tests or old fixtures.
            (
                bdid,
                chunk_index,
                page_from,
                page_to,
                snippet,
                chunk_full,
                similarity,
                embedding,
            ) = row
            exact_machine_scope = False
        else:
            raise ValueError(f"Unexpected dense candidate row width: {len(row)}")

        if embedding is None:
            emb_list = None
        elif isinstance(embedding, list):
            emb_list = embedding
        else:
            value = str(embedding).strip().strip("[]")
            emb_list = [float(x) for x in value.split(",") if x.strip()]

        item = {
            "citation_id": f"{bdid}:p{int(page_from)}-{int(page_to)}:c{int(chunk_index)}",
            "bubble_document_id": str(bdid),
            "chunk_index": int(chunk_index),
            "page_from": int(page_from),
            "page_to": int(page_to),
            "snippet": (snippet or "").strip(),
            "chunk_full": (chunk_full or "").strip(),
            # Keep the raw cosine similarity separate from later routing/ranking
            # scores. Deterministic page/structured helpers also expose a field named
            # ``similarity`` but those values are synthetic and must never prove
            # evidence sufficiency.
            "similarity": float(similarity),
            "semantic_similarity": float(similarity),
            "embedding_list": emb_list or [],
            "exact_machine_scope": bool(exact_machine_scope),
        }

        if query_used is not None:
            item["query_used"] = query_used

        candidates.append(item)

    return candidates

def _db_conn():
    if not (DB_HOST and DB_USER and DB_PASSWORD):
        raise HTTPException(status_code=500, detail="DB env missing")

    kwargs: dict[str, Any] = {
        "host": DB_HOST,
        "dbname": DB_NAME,
        "user": DB_USER,
        "password": DB_PASSWORD,
    }

    # Existing ingest/electrical/Smart Diagnostic behavior is unchanged. Only a live
    # V13 ASK/Root Cause request receives bounded connect/statement timeouts.
    budget = None
    try:
        budget_fn = globals().get("_v13_current_budget")
        budget = budget_fn() if callable(budget_fn) else None
    except Exception:
        budget = None

    assurance_remaining: Optional[float] = None
    try:
        assurance_ctx = globals().get("_V13_ASSURANCE_DEADLINE_CTX")
        assurance_deadline = float(assurance_ctx.get() or 0.0) if assurance_ctx is not None else 0.0
        if assurance_deadline > 0.0:
            assurance_remaining = max(0.1, assurance_deadline - time_module.monotonic())
    except Exception:
        assurance_remaining = None

    if budget is not None and assurance_remaining is None:
        # Preserve the pre-assurance V13 behavior exactly outside the bounded layer.
        budget.ensure_time(1.5)
        remaining = max(1.5, float(budget.remaining()))
        connect_limit = int(globals().get("V13_DB_CONNECT_TIMEOUT_SECONDS", 5) or 5)
        statement_limit = int(globals().get("V13_DB_STATEMENT_TIMEOUT_MS", 9000) or 9000)
        kwargs["connect_timeout"] = max(1, min(connect_limit, int(max(1.0, remaining - 0.5))))
        kwargs["options"] = f"-c statement_timeout={max(1000, min(statement_limit, int(max(1.0, remaining - 0.5) * 1000)))}"
    elif budget is not None or assurance_remaining is not None:
        if budget is not None:
            budget.ensure_time(1.0)
            remaining = max(0.5, float(budget.remaining()))
        else:
            remaining = max(0.5, float(assurance_remaining or 0.5))
        if assurance_remaining is not None:
            remaining = min(remaining, max(0.5, float(assurance_remaining)))
        connect_limit = int(globals().get("V13_DB_CONNECT_TIMEOUT_SECONDS", 5) or 5)
        statement_limit = int(globals().get("V13_DB_STATEMENT_TIMEOUT_MS", 9000) or 9000)
        kwargs["connect_timeout"] = max(1, min(connect_limit, int(max(1.0, remaining - 0.2))))
        kwargs["options"] = f"-c statement_timeout={max(500, min(statement_limit, int(max(0.5, remaining - 0.2) * 1000)))}"

    return psycopg2.connect(**kwargs)


def _vector_literal(vec: list[float]) -> str:
    return "[" + ",".join(f"{x:.8f}" for x in vec) + "]"


def _get_table_columns(cur, table_name: str) -> set[str]:
    cur.execute(
        """
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema='public' AND table_name=%s;
        """,
        (table_name,),
    )
    return {r[0] for r in cur.fetchall()}


def _db_upsert_document_file(company_id: str, bubble_document_id: str, file_url: str) -> None:
    company_id = (company_id or "").strip()
    bubble_document_id = (bubble_document_id or "").strip()
    file_url = (file_url or "").strip()
    if not (company_id and bubble_document_id and file_url):
        return

    conn = _db_conn()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.document_files(company_id, bubble_document_id, file_url, updated_at)
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (company_id, bubble_document_id)
                DO UPDATE SET file_url = EXCLUDED.file_url, updated_at = NOW();
                """,
                (company_id, bubble_document_id, file_url),
            )
        conn.commit()
    finally:
        conn.close()


def _db_upsert_cleaning_meta(
    company_id: str,
    bubble_document_id: str,
    header_norm: set[str],
    footer_norm: set[str],
) -> None:
    company_id = (company_id or "").strip()
    bubble_document_id = (bubble_document_id or "").strip()
    if not (company_id and bubble_document_id):
        return

    header_list = sorted([x for x in (header_norm or set()) if x])
    footer_list = sorted([x for x in (footer_norm or set()) if x])

    conn = _db_conn()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.document_cleaning_meta(company_id, bubble_document_id, header_norm, footer_norm, updated_at)
                VALUES (%s, %s, %s::jsonb, %s::jsonb, NOW())
                ON CONFLICT (company_id, bubble_document_id)
                DO UPDATE SET header_norm = EXCLUDED.header_norm,
                              footer_norm = EXCLUDED.footer_norm,
                              updated_at = NOW();
                """,
                (company_id, bubble_document_id, json.dumps(header_list), json.dumps(footer_list)),
            )
        conn.commit()
    finally:
        conn.close()


def _db_get_cleaning_meta(company_id: str, bubble_document_id: str) -> tuple[set[str], set[str]]:
    company_id = (company_id or "").strip()
    bubble_document_id = (bubble_document_id or "").strip()
    if not (company_id and bubble_document_id):
        return set(), set()

    conn = _db_conn()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT header_norm, footer_norm
                FROM public.document_cleaning_meta
                WHERE company_id=%s AND bubble_document_id=%s
                LIMIT 1;
                """,
                (company_id, bubble_document_id),
            )
            row = cur.fetchone()
            if not row:
                return set(), set()

            h, f = row
            if isinstance(h, str):
                h = json.loads(h or "[]")
            if isinstance(f, str):
                f = json.loads(f or "[]")

            header_set = {str(x) for x in (h or []) if x}
            footer_set = {str(x) for x in (f or []) if x}
            return header_set, footer_set
    finally:
        conn.close()

def _db_get_index_usage(company_id: str, bubble_document_id: Optional[str] = None) -> dict:
    company_id = (company_id or "").strip()
    bubble_document_id = (bubble_document_id or "").strip() if bubble_document_id else None

    if not company_id:
        return {
            "text_chars": 0,
            "chunk_count": 0,
            "est_storage_bytes": 0,
        }

    conn = _db_conn()
    try:
        with conn.cursor() as cur:
            if bubble_document_id:
                cur.execute(
                    """
                    SELECT COALESCE(SUM(text_chars), 0)
                    FROM public.document_pages
                    WHERE company_id=%s
                      AND bubble_document_id=%s;
                    """,
                    (company_id, bubble_document_id),
                )
                text_chars = int(cur.fetchone()[0] or 0)

                cur.execute(
                    """
                    SELECT COUNT(*)
                    FROM public.document_chunks
                    WHERE company_id=%s
                      AND bubble_document_id=%s;
                    """,
                    (company_id, bubble_document_id),
                )
                chunk_count = int(cur.fetchone()[0] or 0)
            else:
                cur.execute(
                    """
                    SELECT COALESCE(SUM(text_chars), 0)
                    FROM public.document_pages
                    WHERE company_id=%s;
                    """,
                    (company_id,),
                )
                text_chars = int(cur.fetchone()[0] or 0)

                cur.execute(
                    """
                    SELECT COUNT(*)
                    FROM public.document_chunks
                    WHERE company_id=%s;
                    """,
                    (company_id,),
                )
                chunk_count = int(cur.fetchone()[0] or 0)

        est_storage_bytes = int(text_chars * 3 + chunk_count * 2000)

        return {
            "text_chars": text_chars,
            "chunk_count": chunk_count,
            "est_storage_bytes": est_storage_bytes,
        }
    finally:
        conn.close()


# -----------------------------------------------------------------------------
# Document-ingest AI-cost ledger
# -----------------------------------------------------------------------------

_INGEST_LEDGER_LOCK = threading.Lock()
_INGEST_LEDGER_READY: Optional[bool] = None
_INGEST_LEDGER_ERROR = ""
_INGEST_METER_CTX = contextvars.ContextVar("machinemind_ingest_meter", default=None)


def _ingest_decimal(value: Any, default: str = "0") -> Decimal:
    try:
        return Decimal(str(value if value is not None else default))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal(default)


def _normalize_ingest_month_key(value: Any) -> str:
    raw = str(value or "").strip()
    if re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", raw):
        return raw
    return datetime.now(timezone.utc).strftime("%Y-%m")


def _effective_ingest_request_key(
    *,
    company_id: str,
    bubble_document_id: str,
    requested_key: Any,
    file_sha256: str = "",
) -> str:
    base = str(requested_key or "").strip() or str(bubble_document_id or "").strip()
    if file_sha256:
        # Same Document + same file is idempotent; changing the file creates a new event.
        base = f"{base}:{file_sha256[:24]}"
    return base or hashlib.sha256(str(company_id or "").encode("utf-8")).hexdigest()[:24]


def _build_ingest_usage_event_id(company_id: str, month_key: str, request_key: str) -> str:
    raw = f"{company_id}\n{month_key}\n{request_key}".encode("utf-8")
    return "ingest_" + hashlib.sha256(raw).hexdigest()[:32]


def _ingest_credits_for_cost(cost_usd: Decimal) -> Decimal:
    credits = max(Decimal("0"), cost_usd) * max(Decimal("0"), INGEST_CREDITS_PER_USD)
    return credits.quantize(Decimal("0.000001"), rounding=ROUND_HALF_UP)


def _ingest_ledger_bootstrap() -> bool:
    global _INGEST_LEDGER_READY, _INGEST_LEDGER_ERROR

    if _INGEST_LEDGER_READY is True:
        return True

    with _INGEST_LEDGER_LOCK:
        if _INGEST_LEDGER_READY is True:
            return True
        if not INGEST_LEDGER_AUTO_DDL:
            _INGEST_LEDGER_READY = True
            return True

        conn = None
        try:
            conn = _db_conn()
            with conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS public.mm_ingest_usage_events (
                        usage_event_id TEXT PRIMARY KEY,
                        request_key TEXT NOT NULL,
                        company_id TEXT NOT NULL,
                        bubble_document_id TEXT NOT NULL,
                        month_key TEXT NOT NULL,
                        status TEXT NOT NULL DEFAULT 'queued',
                        embedding_model TEXT NOT NULL DEFAULT '',
                        embedding_calls BIGINT NOT NULL DEFAULT 0,
                        embedding_input_tokens BIGINT NOT NULL DEFAULT 0,
                        actual_cost_usd NUMERIC(20, 10) NOT NULL DEFAULT 0,
                        ingest_credits NUMERIC(20, 6) NOT NULL DEFAULT 0,
                        pricing_version TEXT NOT NULL DEFAULT '',
                        metering_version TEXT NOT NULL DEFAULT '',
                        usage_json JSONB NOT NULL DEFAULT '{}'::jsonb,
                        attempt_count INTEGER NOT NULL DEFAULT 0,
                        last_error TEXT NOT NULL DEFAULT '',
                        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        completed_at TIMESTAMPTZ
                    );
                    """
                )
                cur.execute(
                    """
                    CREATE INDEX IF NOT EXISTS idx_mm_ingest_usage_company_month
                    ON public.mm_ingest_usage_events(company_id, month_key, updated_at);
                    """
                )
                cur.execute(
                    """
                    CREATE UNIQUE INDEX IF NOT EXISTS uq_mm_ingest_usage_request_month
                    ON public.mm_ingest_usage_events(company_id, month_key, request_key);
                    """
                )
            conn.commit()
            _INGEST_LEDGER_READY = True
            _INGEST_LEDGER_ERROR = ""
            return True
        except Exception as exc:
            if conn is not None:
                try:
                    conn.rollback()
                except Exception:
                    pass
            _INGEST_LEDGER_READY = False
            _INGEST_LEDGER_ERROR = str(exc)[:1000]
            print("INGEST_LEDGER_BOOTSTRAP_FAIL_OPEN", _INGEST_LEDGER_ERROR)
            return False
        finally:
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass


def _ingest_prepare_event(
    *,
    usage_event_id: str,
    request_key: str,
    company_id: str,
    bubble_document_id: str,
    month_key: str,
) -> bool:
    if not _ingest_ledger_bootstrap():
        return False
    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.mm_ingest_usage_events(
                    usage_event_id, request_key, company_id, bubble_document_id,
                    month_key, status, pricing_version, metering_version
                )
                VALUES (%s, %s, %s, %s, %s, 'queued', %s, %s)
                ON CONFLICT (usage_event_id) DO NOTHING;
                """,
                (
                    usage_event_id,
                    request_key,
                    company_id,
                    bubble_document_id,
                    month_key,
                    INGEST_PRICING_VERSION,
                    INGEST_METERING_VERSION,
                ),
            )
        conn.commit()
        return True
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print("INGEST_LEDGER_PREPARE_FAIL_OPEN", str(exc)[:700])
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _ingest_event_snapshot(usage_event_id: str) -> Optional[dict]:
    if not usage_event_id or not _ingest_ledger_bootstrap():
        return None
    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT status, embedding_model, embedding_calls,
                       embedding_input_tokens, actual_cost_usd, ingest_credits,
                       pricing_version, metering_version, usage_json,
                       request_key, company_id, bubble_document_id, month_key,
                       attempt_count, updated_at
                FROM public.mm_ingest_usage_events
                WHERE usage_event_id=%s
                LIMIT 1;
                """,
                (usage_event_id,),
            )
            row = cur.fetchone()
        if not row:
            return None
        return {
            "usage_event_id": usage_event_id,
            "status": str(row[0] or ""),
            "embedding_model": str(row[1] or ""),
            "embedding_calls": int(row[2] or 0),
            "embedding_input_tokens": int(row[3] or 0),
            "actual_cost_usd": float(row[4] or 0),
            "ingest_credits": float(row[5] or 0),
            "pricing_version": str(row[6] or ""),
            "metering_version": str(row[7] or ""),
            "usage_json": row[8] if isinstance(row[8], dict) else {},
            "request_key": str(row[9] or ""),
            "company_id": str(row[10] or ""),
            "bubble_document_id": str(row[11] or ""),
            "month_key": str(row[12] or ""),
            "attempt_count": int(row[13] or 0),
            "updated_at": row[14],
        }
    except Exception as exc:
        print("INGEST_LEDGER_SNAPSHOT_FAIL_OPEN", str(exc)[:700])
        return None
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _ingest_claim_event(usage_event_id: str) -> tuple[str, Optional[dict]]:
    """Return claimed/completed/processing/unavailable and the current snapshot."""
    if not usage_event_id or not _ingest_ledger_bootstrap():
        return "unavailable", None
    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE public.mm_ingest_usage_events
                SET status='processing',
                    attempt_count=attempt_count + 1,
                    updated_at=NOW(),
                    last_error=''
                WHERE usage_event_id=%s
                  AND status <> 'completed'
                  AND (
                      status <> 'processing'
                      OR updated_at < NOW() - (%s * INTERVAL '1 second')
                  )
                RETURNING usage_event_id;
                """,
                (usage_event_id, int(INGEST_PROCESSING_STALE_SECONDS)),
            )
            claimed = cur.fetchone()
        conn.commit()
        if claimed:
            return "claimed", _ingest_event_snapshot(usage_event_id)
        snap = _ingest_event_snapshot(usage_event_id)
        if snap and snap.get("status") == "completed":
            return "completed", snap
        if snap and snap.get("status") == "processing":
            return "processing", snap
        return "unavailable", snap
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print("INGEST_LEDGER_CLAIM_FAIL_OPEN", str(exc)[:700])
        return "unavailable", None
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


class _IngestUsageMeter:
    def __init__(
        self,
        *,
        usage_event_id: str,
        request_key: str,
        company_id: str,
        bubble_document_id: str,
        month_key: str,
    ):
        self.usage_event_id = usage_event_id
        self.request_key = request_key
        self.company_id = company_id
        self.bubble_document_id = bubble_document_id
        self.month_key = month_key
        self.embedding_calls = 0
        self.embedding_input_tokens = 0
        self.embedding_cost_usd = Decimal("0")
        self.provider_usage_calls = 0
        self.fallback_usage_calls = 0

    def record_embedding(self, *, input_tokens: int, usage_source: str) -> None:
        tokens = max(0, int(input_tokens or 0))
        self.embedding_calls += 1
        self.embedding_input_tokens += tokens
        if usage_source == "provider_usage":
            self.provider_usage_calls += 1
        else:
            self.fallback_usage_calls += 1
        self.embedding_cost_usd += (
            Decimal(tokens) * INGEST_PRICE_EMBED_INPUT_USD_PER_MILLION
        ) / Decimal("1000000")

    def usage_dict(self) -> dict:
        cost = self.embedding_cost_usd.quantize(Decimal("0.0000000001"), rounding=ROUND_HALF_UP)
        credits = _ingest_credits_for_cost(cost)
        return {
            "embedding_model": OPENAI_EMBED_MODEL,
            "embedding_calls": self.embedding_calls,
            "embedding_input_tokens": self.embedding_input_tokens,
            "provider_usage_calls": self.provider_usage_calls,
            "fallback_usage_calls": self.fallback_usage_calls,
            "embedding_cost_usd": float(cost),
            "ingest_credits": float(credits),
        }

    def metering_status(self) -> str:
        if self.embedding_calls <= 0:
            return "measured_zero_cost"
        if self.fallback_usage_calls > 0:
            return "estimated_partial"
        return "measured"


def _current_ingest_meter() -> Optional[_IngestUsageMeter]:
    value = _INGEST_METER_CTX.get()
    return value if isinstance(value, _IngestUsageMeter) else None


def _ingest_finalize_event(
    meter: _IngestUsageMeter,
    *,
    status: str,
    error_text: str = "",
) -> Optional[dict]:
    usage = meter.usage_dict()
    if not _ingest_ledger_bootstrap():
        return None

    attempt_cost = _ingest_decimal(usage.get("embedding_cost_usd"))
    attempt_credits = _ingest_decimal(usage.get("ingest_credits"))
    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE public.mm_ingest_usage_events
                SET status=%s,
                    embedding_model=%s,
                    embedding_calls=embedding_calls + %s,
                    embedding_input_tokens=embedding_input_tokens + %s,
                    actual_cost_usd=actual_cost_usd + %s,
                    ingest_credits=ingest_credits + %s,
                    pricing_version=%s,
                    metering_version=%s,
                    usage_json=%s::jsonb,
                    last_error=%s,
                    updated_at=NOW(),
                    completed_at=CASE WHEN %s='completed' THEN NOW() ELSE completed_at END
                WHERE usage_event_id=%s;
                """,
                (
                    status,
                    OPENAI_EMBED_MODEL,
                    int(usage.get("embedding_calls") or 0),
                    int(usage.get("embedding_input_tokens") or 0),
                    str(attempt_cost),
                    str(attempt_credits),
                    INGEST_PRICING_VERSION,
                    INGEST_METERING_VERSION,
                    json.dumps(usage, ensure_ascii=False),
                    str(error_text or "")[:1800],
                    status,
                    meter.usage_event_id,
                ),
            )
        conn.commit()
        return _ingest_event_snapshot(meter.usage_event_id)
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print("INGEST_LEDGER_FINALIZE_FAIL_OPEN", str(exc)[:700])
        return None
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _ingest_month_usage(company_id: str, month_key: str) -> dict:
    month_key = _normalize_ingest_month_key(month_key)
    if not _ingest_ledger_bootstrap():
        return {
            "company_id": company_id,
            "month_key": month_key,
            "ingest_credits_used_month": 0.0,
            "embedding_input_tokens_total": 0,
            "ledger_available": False,
            "ledger_error": _INGEST_LEDGER_ERROR,
        }
    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT COALESCE(SUM(ingest_credits), 0),
                       COALESCE(SUM(embedding_input_tokens), 0),
                       MAX(updated_at)
                FROM public.mm_ingest_usage_events
                WHERE company_id=%s AND month_key=%s;
                """,
                (company_id, month_key),
            )
            row = cur.fetchone() or (0, 0, None)
        return {
            "company_id": company_id,
            "month_key": month_key,
            "ingest_credits_used_month": float(row[0] or 0),
            "embedding_input_tokens_total": int(row[1] or 0),
            "updated_at": row[2].isoformat() if row[2] is not None else None,
            "ledger_available": True,
            "ledger_error": "",
        }
    except Exception as exc:
        print("INGEST_LEDGER_MONTH_FAIL_OPEN", str(exc)[:700])
        return {
            "company_id": company_id,
            "month_key": month_key,
            "ingest_credits_used_month": 0.0,
            "embedding_input_tokens_total": 0,
            "ledger_available": False,
            "ledger_error": str(exc)[:700],
        }
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _ingest_public_fields(
    *,
    meter: Optional[_IngestUsageMeter],
    event_snapshot: Optional[dict],
    month_usage: Optional[dict],
    status_override: str = "",
) -> dict:
    snap = event_snapshot or {}
    usage = dict(snap.get("usage_json") or {})
    if meter is not None and not usage:
        usage = meter.usage_dict()

    actual_credits = float(
        snap.get("ingest_credits")
        if snap.get("ingest_credits") is not None
        else usage.get("ingest_credits") or 0
    )
    status = status_override or (
        meter.metering_status() if meter is not None else str(snap.get("status") or "unknown")
    )
    return {
        "request_key": str(snap.get("request_key") or (meter.request_key if meter else "")),
        "ingest_request_key": str(snap.get("request_key") or (meter.request_key if meter else "")),
        "ingest_usage_event_id": str(
            (meter.usage_event_id if meter else "") or snap.get("usage_event_id") or ""
        ),
        "ingest_month_key": str(snap.get("month_key") or (meter.month_key if meter else "")),
        "ingest_credits_actual": actual_credits,
        "ingest_credits_used_month": float(
            (month_usage or {}).get("ingest_credits_used_month") or 0
        ),
        "ingest_pricing_version": str(snap.get("pricing_version") or INGEST_PRICING_VERSION),
        "ingest_metering_status": status,
        "ingest_metering_version": INGEST_METERING_VERSION,
        "ingest_usage": usage,
    }


def _meter_index_document(func):
    @functools.wraps(func)
    def wrapped(
        payload: IndexDocumentRequest,
        x_ai_internal_secret: Optional[str] = Header(default=None),
    ):
        # Structured Bubble sources (procedures, steps, P&S, photos/videos) also reuse
        # /index/document, but the new monthly quota applies only to uploaded Documents.
        if not bool(payload.ingest_metering_enabled):
            return func(payload, x_ai_internal_secret)

        # Authentication remains owned by the original route. Do not create usage rows
        # for unauthenticated calls.
        if not AI_INTERNAL_SECRET or (x_ai_internal_secret or "").strip() != AI_INTERNAL_SECRET:
            return func(payload, x_ai_internal_secret)

        company_id = str(payload.company_id or "").strip()
        bubble_document_id = str(payload.bubble_document_id or "").strip()
        month_key = _normalize_ingest_month_key(payload.ingest_month_key)
        request_key = str(
            payload.ingest_request_key or payload.trace_id or bubble_document_id
        ).strip()
        usage_event_id = str(payload.ingest_usage_event_id or "").strip() or (
            _build_ingest_usage_event_id(company_id, month_key, request_key)
        )

        _ingest_prepare_event(
            usage_event_id=usage_event_id,
            request_key=request_key,
            company_id=company_id,
            bubble_document_id=bubble_document_id,
            month_key=month_key,
        )
        claim_status, existing = _ingest_claim_event(usage_event_id)

        if claim_status == "completed":
            month_usage = _ingest_month_usage(company_id, month_key)
            return {
                "ok": True,
                "status": "indexed",
                "company_id": company_id,
                "machine_id": str(payload.machine_id or ""),
                "bubble_document_id": bubble_document_id,
                "trace_id": payload.trace_id,
                "deduplicated": True,
                **_ingest_public_fields(
                    meter=None,
                    event_snapshot=existing,
                    month_usage=month_usage,
                    status_override="measured_deduplicated",
                ),
            }

        if claim_status == "processing":
            month_usage = _ingest_month_usage(company_id, month_key)
            return {
                "ok": True,
                "status": "processing",
                "company_id": company_id,
                "machine_id": str(payload.machine_id or ""),
                "bubble_document_id": bubble_document_id,
                "trace_id": payload.trace_id,
                "deduplicated": True,
                **_ingest_public_fields(
                    meter=None,
                    event_snapshot=existing,
                    month_usage=month_usage,
                    status_override="already_processing",
                ),
            }

        meter = _IngestUsageMeter(
            usage_event_id=usage_event_id,
            request_key=request_key,
            company_id=company_id,
            bubble_document_id=bubble_document_id,
            month_key=month_key,
        )
        ctx_token = _INGEST_METER_CTX.set(meter)

        try:
            result = func(payload, x_ai_internal_secret)
        except Exception as exc:
            _INGEST_METER_CTX.reset(ctx_token)
            snapshot = _ingest_finalize_event(meter, status="error", error_text=str(exc))
            month_usage = _ingest_month_usage(company_id, month_key)
            print(
                "INGEST_METER_FINAL_ERROR",
                json.dumps(
                    _ingest_public_fields(
                        meter=meter,
                        event_snapshot=snapshot,
                        month_usage=month_usage,
                    ),
                    ensure_ascii=False,
                ),
            )
            raise

        _INGEST_METER_CTX.reset(ctx_token)
        final_status = "completed" if isinstance(result, dict) and result.get("ok") is True else "error"
        snapshot = _ingest_finalize_event(
            meter,
            status=final_status,
            error_text="" if final_status == "completed" else str((result or {}).get("error") or "index failed"),
        )
        month_usage = _ingest_month_usage(company_id, month_key)
        if isinstance(result, dict):
            result.update(
                _ingest_public_fields(
                    meter=meter,
                    event_snapshot=snapshot,
                    month_usage=month_usage,
                )
            )
        print(
            "INGEST_METER_FINAL",
            json.dumps(
                _ingest_public_fields(
                    meter=meter,
                    event_snapshot=snapshot,
                    month_usage=month_usage,
                ),
                ensure_ascii=False,
            ),
        )
        return result

    return wrapped


def _fetch_document_file_map(company_id: str, doc_ids: list[str]) -> dict[str, str]:
    company_id = (company_id or "").strip()
    doc_ids = sorted({str(x or "").strip() for x in (doc_ids or []) if str(x or "").strip()})
    if not company_id or not doc_ids:
        return {}

    conn = _db_conn()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT bubble_document_id, file_url
                FROM public.document_files
                WHERE company_id = %s
                  AND bubble_document_id = ANY(%s);
                """,
                (company_id, doc_ids),
            )
            rows = cur.fetchall()
            return {str(bdid): (url or "").strip() for (bdid, url) in rows if bdid and url}
    finally:
        conn.close()


def _safe_int(value: Any, default: int = 0) -> int:
    try:
        if value is None or value == "":
            return default
        return int(value)
    except Exception:
        return default


def _clean_display_text(value: Any, max_len: int = 140) -> str:
    text = re.sub(r"\s+", " ", str(value or "").strip())
    text = text.strip(" -–—:;,.\t\n")
    if max_len and len(text) > max_len:
        text = text[: max_len - 1].rstrip() + "…"
    return text


def _title_from_file_url(file_url: str) -> str:
    file_url = str(file_url or "").strip()
    if not file_url:
        return ""

    try:
        parsed = urlparse(file_url.split("#", 1)[0].split("?", 1)[0])
        name = unquote((parsed.path or "").rstrip("/").split("/")[-1])
    except Exception:
        name = ""

    name = re.sub(r"[_-]+", " ", name or "")
    name = re.sub(r"\.(pdf|docx?|xlsx?|pptx?|txt|png|jpe?g|webp|mp4|mov|avi)$", "", name, flags=re.IGNORECASE)
    return _clean_display_text(name, max_len=90)


def _parse_structured_source_fields(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for raw_line in str(text or "").replace("\r", "\n").split("\n"):
        line = raw_line.strip()
        if not line or ":" not in line:
            continue
        key, value = line.split(":", 1)
        key = re.sub(r"\s+", "_", key.strip().lower())
        value = _clean_display_text(value, max_len=240)
        if key and value and key not in fields:
            fields[key] = value
    return fields


def _source_display_meta_for_citation(c: dict, file_url: str = "") -> dict:
    c = c or {}
    bdid = str(c.get("bubble_document_id") or "").strip()
    source_kind = _source_type_from_document_id(bdid)
    raw_prefix = bdid.split(":", 1)[0].strip().lower() if ":" in bdid else ""
    if source_kind == "manual" and raw_prefix in {"problem_solution", "problemsolution"}:
        source_kind = "ps"
    source_id = bdid.split(":", 1)[1].strip() if ":" in bdid else bdid

    snippet_for_meta = (
        c.get("chunk_full")
        or c.get("snippet")
        or c.get("snippet_clean")
        or ""
    )
    fields = _parse_structured_source_fields(snippet_for_meta)

    page_from = _safe_int(c.get("page_from"), 0)
    page_to = _safe_int(c.get("page_to"), page_from)

    display_title = ""
    display_location = ""
    display_label = ""

    if source_kind == "procedure":
        title = _clean_display_text(fields.get("title") or fields.get("short_description") or "Procedura", max_len=90)
        display_title = title
        display_label = f"Procedura: {title}" if title else "Procedura"

    elif source_kind == "step":
        title = _clean_display_text(fields.get("title") or fields.get("description") or "Step", max_len=90)
        step_no = _clean_display_text(fields.get("step_number") or "", max_len=20)
        display_title = title
        display_location = f"Step {step_no}" if step_no else "Step"
        if step_no and title and title.lower() != "step":
            display_label = f"Step {step_no}: {title}"
        elif title and title.lower() != "step":
            display_label = f"Step: {title}"
        else:
            display_label = display_location

    elif source_kind == "ps":
        title = _clean_display_text(fields.get("title") or fields.get("category") or fields.get("description") or "P&S", max_len=90)
        category = _clean_display_text(fields.get("category") or "", max_len=60)
        display_title = title
        if category and category.lower() not in title.lower():
            display_label = f"P&S: {title} — Categoria: {category}"
        else:
            display_label = f"P&S: {title}" if title else "P&S"

    elif source_kind == "md_photo":
        title = _clean_display_text(fields.get("title") or fields.get("description") or "Foto", max_len=90)
        display_title = title
        display_label = f"Foto: {title}" if title and title.lower() != "foto" else "Foto"

    elif source_kind == "md_video":
        title = _clean_display_text(fields.get("title") or fields.get("description") or "Video", max_len=90)
        display_title = title
        display_label = f"Video: {title}" if title and title.lower() != "video" else "Video"

    else:
        source_kind = "document"
        title = (
            _clean_display_text(str(c.get("display_title") or ""), max_len=90)
            or _title_from_file_url(file_url)
            or "Documento"
        )
        display_title = title
        if page_from > 0 and page_to > page_from:
            display_location = f"pag. {page_from}/{page_to}"
        elif page_from > 0:
            display_location = f"pag. {page_from}"
        else:
            display_location = ""
        display_label = f"{display_title} - {display_location}" if display_location else display_title

    display_title = _clean_display_text(display_title, max_len=100)
    display_location = _clean_display_text(display_location, max_len=60)
    display_label = _clean_display_text(display_label or display_title or bdid, max_len=160)

    return {
        "source_type": source_kind,
        "source_id": source_id,
        "is_structured_source": bool(_is_structured_source_key(bdid) or source_kind in STRUCTURED_SOURCE_TYPES),
        "display_title": display_title,
        "display_location": display_location,
        "display_label": display_label,
    }




def _structured_source_snippet_for_display(c: dict, *, max_len: int = 520) -> str:
    """Human-readable snippet for Bubble structured sources.

    Structured records are indexed with machine-readable labels such as
    SOURCE_TYPE, STEP_NUMBER, DESCRIPTION. Those are useful for retrieval, but
    they must not be shown raw in the customer UI.
    """
    c = c or {}
    bdid = str(c.get("bubble_document_id") or "").strip()
    source_kind = _source_type_from_document_id(bdid)
    raw_text = str(c.get("chunk_full") or c.get("snippet") or c.get("snippet_clean") or "")
    fields = _parse_structured_source_fields(raw_text)

    def val(*keys: str, limit: int = 240) -> str:
        for k in keys:
            v = _clean_display_text(fields.get(k) or "", max_len=limit)
            if v:
                return v
        return ""

    lines: list[str] = []
    if source_kind == "procedure":
        title = val("title", limit=90) or "Procedura"
        ptype = val("procedure_type", limit=80)
        desc = val("short_description", "description", limit=260)
        lines.append(f"Procedura: {title}")
        if ptype:
            lines.append(f"Tipo: {ptype}")
        if desc:
            lines.append(f"Descrizione: {desc}")

    elif source_kind == "step":
        step_no = val("step_number", limit=20)
        title = val("title", limit=90) or "Step"
        desc = val("description", limit=320)
        prefix = f"Step {step_no}:" if step_no else "Step:"
        lines.append(f"{prefix} {title}")
        if desc and desc.lower() not in title.lower():
            lines.append(desc)

    elif source_kind == "ps":
        title = val("title", limit=100) or "Problema/Soluzione"
        category = val("category", limit=70)
        desc = val("description", limit=300)
        sol = val("solution", limit=300)
        notes = val("notes", limit=220)
        lines.append(f"P&S: {title}")
        if category:
            lines.append(f"Categoria: {category}")
        if desc:
            lines.append(f"Problema: {desc}")
        if sol:
            lines.append(f"Soluzione: {sol}")
        if notes:
            lines.append(f"Note: {notes}")

    elif source_kind == "md_photo":
        title = val("title", limit=100) or "Foto"
        desc = val("description", limit=320)
        lines.append(f"Foto: {title}")
        if desc and desc.lower() not in title.lower():
            lines.append(desc)

    elif source_kind == "md_video":
        title = val("title", limit=100) or "Video"
        desc = val("description", limit=320)
        lines.append(f"Video: {title}")
        if desc and desc.lower() not in title.lower():
            lines.append(desc)

    else:
        return ""

    text = " — ".join([x for x in lines if x]).strip()
    text = re.sub(r"\bSOURCE_TYPE\s*:\s*[^—]+", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+", " ", text).strip(" -–—")
    return _clean_display_text(text, max_len=max_len)


def _format_citation_note_lines(citations: list[dict], *, language: str = "it", max_items: int = 6) -> str:
    citations = [c for c in (citations or []) if isinstance(c, dict)]
    if not citations:
        return ""

    header = "Evidence used:" if str(language or "").lower().startswith("en") else "Fonti utilizzate:"
    lines = [header]
    seen = set()

    for c in citations:
        label = _clean_display_text(c.get("display_label") or c.get("citation_id") or "Fonte", max_len=160)
        if not label or label in seen:
            continue
        seen.add(label)

        snippet = _clean_display_text(c.get("snippet_clean") or c.get("snippet") or "", max_len=260)
        if snippet:
            lines.append(f"- {label} — {snippet}")
        else:
            lines.append(f"- {label}")

        if len(lines) - 1 >= max_items:
            break

    return "\n".join(lines).strip()



def _build_rg_links(company_id: str, citations: list[dict]) -> list[dict]:
    if not citations:
        return []

    doc_ids = sorted(
        {
            str(c.get("bubble_document_id") or "").strip()
            for c in citations
            if isinstance(c, dict) and c.get("bubble_document_id")
        }
    )
    if not doc_ids:
        return []

    file_map = _fetch_document_file_map(company_id, doc_ids)

    out: list[dict] = []
    for c in citations:
        if not isinstance(c, dict):
            continue
        bdid = str(c.get("bubble_document_id") or "").strip()
        if not bdid:
            continue

        file_url = file_map.get(bdid)
        if not file_url:
            continue

        base = file_url.split("#", 1)[0]
        page_from = _safe_int(c.get("page_from"), 1)
        if page_from < 1:
            page_from = 1

        meta = _source_display_meta_for_citation(c, file_url=file_url)
        is_structured = bool(meta.get("is_structured_source"))
        final_url = file_url if is_structured else f"{base}#page={page_from}"

        source_type = str(meta.get("source_type") or c.get("source_type") or "document").strip().lower()
        if bool(c.get("ask_structured_manual_support")):
            evidence_role = "manual_support"
        elif bool(c.get("ask_structured_direct")):
            evidence_role = source_type or "structured"
        else:
            evidence_role = str(c.get("evidence_role") or source_type or "document").strip().lower()

        out.append(
            {
                "citation_id": c.get("citation_id"),
                "bubble_document_id": bdid,
                "page_from": _safe_int(c.get("page_from"), page_from),
                "page_to": _safe_int(c.get("page_to"), page_from),
                "url": final_url,
                "evidence_role": evidence_role,
                "ask_structured_manual_support": bool(c.get("ask_structured_manual_support")),
                "ask_manual_support_kind": str(c.get("ask_manual_support_kind") or ""),
                **meta,
            }
        )

    return out


def _normalize_structured_source_type(source_type: str) -> str:
    s = re.sub(r"[\s\-]+", "_", str(source_type or "").strip().lower())

    aliases = {
        "procedure": "procedure",
        "step": "step",
        "ps": "ps",
        "problemsolution": "ps",
        "problem_solution": "ps",
        "problem_solution_item": "ps",
        "md_photo": "md_photo",
        "machine_detail_photo": "md_photo",
        "photo_machine_detail": "md_photo",
        "md_video": "md_video",
        "machine_detail_video": "md_video",
        "video_machine_detail": "md_video",
    }

    s = aliases.get(s, s)
    if s not in STRUCTURED_SOURCE_TYPES:
        raise HTTPException(status_code=400, detail=f"Unsupported source_type: {source_type}")

    return s


def _build_structured_source_key(source_type: str, source_id: str) -> str:
    st = _normalize_structured_source_type(source_type)
    sid = str(source_id or "").strip()
    if not sid:
        raise HTTPException(status_code=400, detail="Missing source_id")
    return f"{st}:{sid}"


STRUCTURED_RELATION_PROCEDURE_STEP = "procedure_step"


def _normalize_structured_source_key(source_type: str, source_id_or_key: Any) -> str:
    raw = str(source_id_or_key or "").strip()
    if not raw:
        return ""
    prefix = f"{_normalize_structured_source_type(source_type)}:"
    return raw if raw.lower().startswith(prefix.lower()) else prefix + raw


def _parent_procedure_source_key(payload: StructuredSourceIngestRequest) -> str:
    parent_id = str(payload.parent_procedure_id or "").strip()
    if not parent_id:
        return ""
    return _normalize_structured_source_key("procedure", parent_id)


def _db_upsert_structured_source_relation(
    *,
    company_id: str,
    machine_id: str,
    child_source_key: str,
    parent_source_key: str,
    ordinal: Optional[int],
    relation_source: str,
    metadata: Optional[dict] = None,
) -> bool:
    """Write only relation metadata; never re-embed or rewrite the source."""
    if not (company_id and machine_id and child_source_key and parent_source_key):
        return False

    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.structured_source_relations(
                    company_id,
                    machine_id,
                    child_source_key,
                    parent_source_key,
                    relation_type,
                    child_source_type,
                    parent_source_type,
                    ordinal,
                    relation_source,
                    metadata,
                    created_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, 'step', 'procedure', %s, %s, %s::jsonb, NOW(), NOW())
                ON CONFLICT (company_id, child_source_key, relation_type)
                DO UPDATE SET
                    machine_id = EXCLUDED.machine_id,
                    parent_source_key = EXCLUDED.parent_source_key,
                    ordinal = EXCLUDED.ordinal,
                    relation_source = EXCLUDED.relation_source,
                    metadata = EXCLUDED.metadata,
                    updated_at = NOW();
                """,
                (
                    company_id,
                    machine_id,
                    child_source_key,
                    parent_source_key,
                    STRUCTURED_RELATION_PROCEDURE_STEP,
                    int(ordinal) if ordinal is not None else None,
                    str(relation_source or "bubble").strip() or "bubble",
                    json.dumps(metadata or {}, ensure_ascii=False),
                ),
            )
        conn.commit()
        return True
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        # Migration can be rolled out before code or vice versa. Relation failure
        # must not break normal source ingest; retrieval has a text fallback.
        print("STRUCTURED_RELATION_UPSERT_FAIL_OPEN", str(exc)[:700])
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _db_fetch_related_step_pages(
    *,
    company_id: str,
    machine_id: str,
    parent_source_key: str,
    text_chars: int,
) -> list[tuple]:
    """Return canonical Step children in Bubble order without semantic guessing."""
    if not (company_id and machine_id and parent_source_key):
        return []

    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    r.child_source_key,
                    r.ordinal,
                    p.machine_id,
                    p.page_number,
                    LEFT(COALESCE(p.text, ''), %s) AS page_text
                FROM public.structured_source_relations AS r
                JOIN public.document_pages AS p
                  ON p.company_id = r.company_id
                 AND p.bubble_document_id = r.child_source_key
                WHERE r.company_id = %s
                  AND r.machine_id = %s
                  AND r.parent_source_key = %s
                  AND r.relation_type = %s
                  AND p.text IS NOT NULL
                  AND length(p.text) > 10
                ORDER BY
                    r.ordinal NULLS LAST,
                    r.child_source_key,
                    p.page_number;
                """,
                (
                    int(text_chars),
                    company_id,
                    machine_id,
                    parent_source_key,
                    STRUCTURED_RELATION_PROCEDURE_STEP,
                ),
            )
            return list(cur.fetchall())
    except Exception as exc:
        print("STRUCTURED_RELATION_READ_FALLBACK", str(exc)[:700])
        return []
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _db_delete_structured_relations_for_source(company_id: str, source_key: str) -> int:
    if not (company_id and source_key):
        return 0
    conn = None
    try:
        conn = _db_conn()
        with conn.cursor() as cur:
            cur.execute(
                """
                DELETE FROM public.structured_source_relations
                WHERE company_id=%s
                  AND (child_source_key=%s OR parent_source_key=%s);
                """,
                (company_id, source_key, source_key),
            )
            deleted = int(cur.rowcount or 0)
        conn.commit()
        return deleted
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print("STRUCTURED_RELATION_DELETE_SOURCE_FAIL_OPEN", str(exc)[:500])
        return 0
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


